"""GENERATED by the LeetCode extension. Edits are overwritten.

One generic runner serves every Python problem, because Python has real
reflection. Contract, matching assets/harness/Runner.cs:

    runner.py <solution-file> <testcase-file> [expected-file] [--paramindex N]

Exit codes: 0 every case passed, 1 at least one case failed, 2 usage or
scaffolding error.
"""

from __future__ import annotations

import inspect
import sys
import time
import typing

sys.path.insert(0, str(__import__("pathlib").Path(__file__).resolve().parent))

import lcjson  # noqa: E402
from loader import load_solution  # noqa: E402


def unwrap_optional(annotation: object) -> object:
    origin = typing.get_origin(annotation)
    if origin is typing.Union:
        arguments = [a for a in typing.get_args(annotation) if a is not type(None)]
        if len(arguments) == 1:
            return arguments[0]
    return annotation


def coerce(raw: str, annotation: object) -> object:
    """Turns one JSON line into the value the annotation asks for."""
    value = lcjson.loads(raw)
    if annotation is inspect.Parameter.empty:
        return value

    target = unwrap_optional(annotation)

    if target is lcjson.ListNode:
        return lcjson.build_list(value)
    if target is lcjson.TreeNode:
        return lcjson.build_tree(value)

    origin = typing.get_origin(target)
    if origin in (list, typing.List) and isinstance(value, list):
        element = unwrap_optional((typing.get_args(target) or (None,))[0])
        if element is lcjson.ListNode:
            return [lcjson.build_list(item) for item in value]
        if element is lcjson.TreeNode:
            return [lcjson.build_tree(item) for item in value]
    return value


def render(value: object) -> str:
    if isinstance(value, lcjson.ListNode):
        return lcjson.dumps(lcjson.flatten_list(value))
    if isinstance(value, lcjson.TreeNode):
        return lcjson.dumps(lcjson.flatten_tree(value))
    if isinstance(value, list) and value and isinstance(value[0], lcjson.ListNode):
        return lcjson.dumps([lcjson.flatten_list(item) for item in value])
    return lcjson.dumps(value)


def annotations_for(function: object, module: object) -> dict:
    try:
        return typing.get_type_hints(function, globalns=vars(module))
    except Exception:
        return getattr(function, "__annotations__", {}) or {}


def report(case_index: int, expected: list, actual: str) -> int:
    if case_index >= len(expected):
        return 0
    if lcjson.normalize(expected[case_index]) == lcjson.normalize(actual):
        print("  PASS")
        return 0
    print(f"  FAIL    expected = {expected[case_index]}")
    return 1


def find_design_class(first_line: str, module: object):
    if not first_line.startswith("["):
        return None, None
    try:
        operations = lcjson.loads(first_line)
    except ValueError:
        return None, None
    if not isinstance(operations, list) or not operations:
        return None, None
    if not all(isinstance(item, str) for item in operations):
        return None, None
    candidate = getattr(module, operations[0], None)
    if inspect.isclass(candidate):
        return candidate, operations
    return None, None


def run_standard(module, lines, expected, param_index) -> int:
    solution_class = getattr(module, "Solution", None)
    if solution_class is None:
        print(
            "No 'Solution' class found. LeetCode python3 submissions declare 'class Solution'.",
            file=sys.stderr,
        )
        return 2

    methods = [
        function
        for name, function in inspect.getmembers(solution_class, inspect.isfunction)
        if not name.startswith("_")
    ]
    if not methods:
        print(f"No public method found on {solution_class.__name__}.", file=sys.stderr)
        return 2
    method = methods[0]
    if len(methods) > 1:
        print(
            f"Note: {len(methods)} public methods on {solution_class.__name__}; using '{method.__name__}'.",
            file=sys.stderr,
        )

    signature = inspect.signature(method)
    parameters = [p for p in signature.parameters.values() if p.name != "self"]
    hints = annotations_for(method, module)
    arity = max(len(parameters), 1)

    if len(lines) % arity != 0:
        print(
            f"{method.__name__} takes {len(parameters)} argument(s) but the test file "
            f"has {len(lines)} line(s). Each test case needs one line per argument.",
            file=sys.stderr,
        )
        return 2

    failures = 0
    for case_index in range(len(lines) // arity):
        raw = lines[case_index * arity : (case_index + 1) * arity]
        arguments = [
            coerce(raw[i], hints.get(parameter.name, inspect.Parameter.empty))
            for i, parameter in enumerate(parameters)
        ]

        print(f"--- Case {case_index + 1} ---")
        for parameter, value in zip(parameters, raw):
            print(f"  {parameter.name} = {value}")

        instance = solution_class()
        started = time.perf_counter()
        result = method(instance, *arguments)
        elapsed = (time.perf_counter() - started) * 1000

        if result is None and arguments:
            # Void methods mutate in place; metaData.output.paramindex says which
            # argument the judge reads back.
            actual = render(arguments[param_index])
            print(f"  mutated = {parameters[param_index].name} = {actual}")
        else:
            actual = render(result)

        print(f"  output  = {actual}")
        failures += report(case_index, expected, actual)
        print(f"  elapsed = {elapsed:.3f} ms")
        print()

    return 1 if failures else 0


def run_design(design_class, lines, expected) -> int:
    failures = 0
    for line in range(0, len(lines) - 1, 2):
        case_index = line // 2
        operations = lcjson.loads(lines[line])
        argument_sets = lcjson.loads(lines[line + 1])

        print(f"--- Case {case_index + 1} ---")
        print(f"  ops  = {lines[line]}")
        print(f"  args = {lines[line + 1]}")

        outputs = []
        instance = None
        started = time.perf_counter()
        for step, operation in enumerate(operations):
            call_arguments = argument_sets[step] if step < len(argument_sets) else []
            if step == 0:
                instance = design_class(*call_arguments)
                outputs.append("null")
                continue
            member = getattr(instance, operation, None)
            if member is None:
                print(
                    f"  No method '{operation}' on {design_class.__name__}.",
                    file=sys.stderr,
                )
                return 2
            value = member(*call_arguments)
            outputs.append("null" if value is None else render(value))
        elapsed = (time.perf_counter() - started) * 1000

        actual = "[" + ",".join(outputs) + "]"
        print(f"  output  = {actual}")
        failures += report(case_index, expected, actual)
        print(f"  elapsed = {elapsed:.3f} ms")
        print()

    return 1 if failures else 0


def main(argv: list) -> int:
    param_index = 0
    if "--paramindex" in argv:
        position = argv.index("--paramindex")
        param_index = int(argv[position + 1])
        del argv[position : position + 2]

    if len(argv) < 3:
        print(
            "Usage: runner.py <solution-file> <testcase-file> [expected-file] [--paramindex N]",
            file=sys.stderr,
        )
        return 2

    module = load_solution(argv[1])
    lines = lcjson.read_values(argv[2])
    expected = lcjson.read_values(argv[3]) if len(argv) > 3 else []

    if not lines:
        print(
            "No test cases found. Add one JSON value per argument, per line.",
            file=sys.stderr,
        )
        return 2

    design_class, _ = find_design_class(lines[0], module)
    if design_class is not None:
        return run_design(design_class, lines, expected)
    return run_standard(module, lines, expected, param_index)


if __name__ == "__main__":
    sys.exit(main(sys.argv))
